The CodeThe ExplanationThe Terminal Output <pre><code>package main

import (
    "context"
    "encoding/json"
    "fmt"
    "log"
    "time"

    "github.com/redis/go-redis/v9"
)

type User struct {
    ID    int64  `json:"id"`
    Name  string `json:"name"`
    Email string `json:"email"`
}

type CacheAside struct {
    redis    *redis.Client
    ttl      time.Duration
}

func NewCacheAside(rdb *redis.Client, ttl time.Duration) *CacheAside {
    return &amp;CacheAside{redis: rdb, ttl: ttl}
}

func (c *CacheAside) Get(ctx context.Context, key string, loader func() (interface{}, error)) (interface{}, error) {
    val, err := c.redis.Get(ctx, key).Result()
    if err == nil {
        var result interface{}
        json.Unmarshal([]byte(val), &amp;result)
        return result, nil
    }

    if err != redis.Nil {
        return nil, err
    }

    data, err := loader()
    if err != nil {
        return nil, err
    }

    jsonData, _ := json.Marshal(data)
    c.redis.Set(ctx, key, jsonData, c.ttl)

    return data, nil
}

func (c *CacheAside) Invalidate(ctx context.Context, key string) error {
    return c.redis.Del(ctx, key).Err()
}

func main() {
    rdb := redis.NewClient(&amp;redis.Options{Addr: "localhost:6379"})
    cache := NewCacheAside(rdb, 5*time.Minute)

    ctx := context.Background()

    loader := func() (interface{}, error) {
        fmt.Println("Loading from database...")
        return User{ID: 1, Name: "Alice", Email: "alice@example.com"}, nil
    }

    user, err := cache.Get(ctx, "user:1", loader)
    if err != nil {
        log.Fatal(err)
    }
    fmt.Printf("First get: %+v\n", user)

    user, err = cache.Get(ctx, "user:1", loader)
    if err != nil {
        log.Fatal(err)
    }
    fmt.Printf("Second get (cached): %+v\n", user)
}
</code></pre> <ul> <li>Cache-Aside: Application manages cache explicitly</li> <li>Loader function: Fetches data from source on cache miss</li> <li>JSON serialization: Store structured data</li> <li>Invalidate: Remove cached value on updates</li> </ul> <pre><code>Loading from database...
First get: {id:1 name:Alice email:alice@example.com}
Second get (cached): {id:1 name:Alice email:alice@example.com}
</code></pre> <p>Cache-Aside Flow</p> <ol> <li>Check cache</li> <li>If miss, load from source</li> <li>Store in cache</li> <li>Return data</li> </ol>

The CodeThe ExplanationThe Terminal Output <pre><code>package main

import (
    "context"
    "encoding/json"
    "fmt"
    "log"
    "time"

    "github.com/redis/go-redis/v9"
)

type User struct {
    ID    int64  `json:"id"`
    Name  string `json:"name"`
}

type WriteThrough struct {
    redis *redis.Client
    ttl   time.Duration
}

func NewWriteThrough(rdb *redis.Client, ttl time.Duration) *WriteThrough {
    return &amp;WriteThrough{redis: rdb, ttl: ttl}
}

func (wt *WriteThrough) Set(ctx context.Context, key string, value interface{}) error {
    jsonData, err := json.Marshal(value)
    if err != nil {
        return err
    }

    return wt.redis.Set(ctx, key, jsonData, wt.ttl).Err()
}

func (wt *WriteThrough) Get(ctx context.Context, key string) (interface{}, error) {
    val, err := wt.redis.Get(ctx, key).Result()
    if err != nil {
        return nil, err
    }

    var result interface{}
    json.Unmarshal([]byte(val), &amp;result)
    return result, nil
}

func (wt *WriteThrough) Delete(ctx context.Context, key string) error {
    return wt.redis.Del(ctx, key).Err()
}

func main() {
    rdb := redis.NewClient(&amp;redis.Options{Addr: "localhost:6379"})
    wt := NewWriteThrough(rdb, 5*time.Minute)

    ctx := context.Background()

    user := User{ID: 1, Name: "Alice"}

    err := wt.Set(ctx, "user:1", user)
    if err != nil {
        log.Fatal(err)
    }
    fmt.Println("Written to cache")

    cached, err := wt.Get(ctx, "user:1")
    if err != nil {
        log.Fatal(err)
    }
    fmt.Printf("Read from cache: %+v\n", cached)
}
</code></pre> <ul> <li>Write-Through: Writes go to cache and database simultaneously</li> <li>Immediate consistency: Cache always has latest data</li> <li>Simple implementation: Write once, read from cache</li> </ul> <pre><code>Written to cache
Read from cache: map[id:1 name:Alice]
</code></pre>

Timeout PatternThe ExplanationThe Terminal OutputDone Channel CancellationThe ExplanationThe Terminal Output <pre><code>package main

import (
    "fmt"
    "time"
)

func slowOperation(ch chan&lt;- string) {
    time.Sleep(3 * time.Second)
    ch &lt;- "result"
}

func main() {
    ch := make(chan string, 1)
    go slowOperation(ch)

    select {
    case result := &lt;-ch:
        fmt.Println("Got result:", result)
    case &lt;-time.After(2 * time.Second):
        fmt.Println("Timeout: operation took too long")
    }
}
</code></pre> <ul> <li><code>time.After(d)</code>: Returns a channel that sends after duration <code>d</code></li> <li>Race between operations: First case to complete wins</li> <li>Timeout pattern: Common for wrapping slow operations with deadlines</li> </ul> <pre><code>Timeout: operation took too long
</code></pre> <pre><code>package main

import (
    "fmt"
    "time"
)

func worker(done &lt;-chan struct{}) {
    for {
        select {
        case &lt;-done:
            fmt.Println("Worker: shutting down gracefully")
            return
        default:
            fmt.Println("Worker: doing work...")
            time.Sleep(500 * time.Millisecond)
        }
    }
}

func main() {
    done := make(chan struct{})

    go worker(done)

    // Let worker run for 2 seconds
    time.Sleep(2 * time.Second)
    close(done)

    time.Sleep(100 * time.Millisecond)
    fmt.Println("Main: worker stopped")
}
</code></pre> <ul> <li><code>close(done)</code>: Broadcasts shutdown signal to all goroutines listening on <code>done</code></li> <li>Non-blocking check: <code>default</code> case keeps the worker doing useful work</li> <li>Graceful shutdown: Worker finishes current iteration and exits cleanly</li> </ul> <pre><code>Worker: doing work...
Worker: doing work...
Worker: doing work...
Worker: doing work...
Worker: shutting down gracefully
Main: worker stopped
</code></pre>

Pattern: Error AccumulationThe ExplanationThe Terminal OutputPattern: Error Handling at BoundariesThe ExplanationThe Terminal Output <pre><code>package main

import (
    "errors"
    "fmt"
)

type MultiError struct {
    errors []error
}

func (m *MultiError) Add(err error) {
    if err != nil {
        m.errors = append(m.errors, err)
    }
}

func (m *MultiError) Error() string {
    msgs := make([]string, len(m.errors))
    for i, err := range m.errors {
        msgs[i] = err.Error()
    }
    return fmt.Sprintf("%d errors: %s", len(m.errors),
        errors.Join(m.errors...))
}

func (m *MultiError) Unwrap() []error {
    return m.errors
}

func validate(name string, age int, email string) error {
    me := &amp;MultiError{}

    if name == "" {
        me.Add(fmt.Errorf("name is required"))
    }
    if age &lt; 0 || age &gt; 150 {
        me.Add(fmt.Errorf("age must be between 0 and 150, got %d", age))
    }
    if email == "" {
        me.Add(fmt.Errorf("email is required"))
    }

    if len(me.errors) == 0 {
        return nil
    }
    return me
}

func main() {
    err := validate("", -5, "")
    if err != nil {
        fmt.Printf("Validation failed:\n%v\n", err)
    }
}
</code></pre> <ul> <li><code>MultiError</code>: Collects multiple errors into a single value</li> <li><code>errors.Join</code>: Go 1.20+ joins multiple errors into one</li> <li>Validation: Common use case where multiple fields can fail independently</li> <li><code>Unwrap() []error</code>: Returns all errors for inspection</li> </ul> <pre><code>Validation failed:
3 errors: name is required
age must be between 0 and 150, got -5
email is required
</code></pre> <pre><code>package main

import (
    "fmt"
    "log"
    "os"
)

func processFile(path string) error {
    file, err := os.Open(path)
    if err != nil {
        return fmt.Errorf("open file: %w", err)
    }
    defer file.Close()

    // Process file...
    fmt.Printf("Processing %s\n", path)
    return nil
}

func main() {
    // Library: return errors for callers to handle
    // Application: handle errors at the boundary

    files := []string{"file1.txt", "file2.txt"}

    for _, f := range files {
        if err := processFile(f); err != nil {
            // At the application boundary: log and continue
            log.Printf("Skipping %s: %v\n", f, err)
            continue
        }
        fmt.Printf("✓ Processed %s\n", f)
    }
}
</code></pre> <ul> <li>Library code: Return errors; let the caller decide how to handle them</li> <li>Application code: Handle errors at boundaries (main, handlers, CLI entry points)</li> <li><code>log.Printf</code>: Log the error and continue with the next file</li> <li>Don't ignore errors: Always check <code>err != nil</code> or use <code>_</code> explicitly</li> </ul> <pre><code>Skipping file1.txt: open file1.txt: no such file or directory
Skipping file2.txt: open file2.txt: no such file or directory
</code></pre>

Production GC ConfigurationThe ExplanationThe Terminal Output <pre><code>package main

import (
    "fmt"
    "runtime"
    "runtime/debug"
)

func main() {
    // Strategy 1: Balanced (default)
    debug.SetGCPercent(100)

    // Strategy 2: Low memory with GOMEMLIMIT (Go 1.19+)
    debug.SetMemoryLimit(512 * 1024 * 1024) // 512 MB

    // Strategy 3: High throughput (disable GC for batch jobs)
    // debug.SetGCPercent(-1) // equivalent to GOGC=off

    // Monitor GC frequency
    var m runtime.MemStats
    runtime.ReadMemStats(&amp;m)
    fmt.Printf("GC configured: GOGC=100, GOMEMLIMIT=512MB\n")
    fmt.Printf("Initial heap: %d KB\n", m.Alloc/1024)

    // Run workload
    for i := 0; i &lt; 100; i++ {
        data := make([]byte, 100*1024)
        _ = data
    }

    runtime.ReadMemStats(&amp;m)
    fmt.Printf("After workload: %d KB, GCs: %d, Pause: %d μs\n",
        m.Alloc/1024, m.NumGC, m.PauseTotalNs/1000)
}
</code></pre> <ul> <li>Balanced (GOGC=100): Good for most applications</li> <li>GOMEMLIMIT: Hard memory ceiling — GC becomes aggressive near limit</li> <li>Batch processing: <code>GOGC=off</code> eliminates GC overhead for short-lived processes</li> <li>Monitor: Use <code>ReadMemStats</code> to validate your configuration</li> </ul> <pre><code>GC configured: GOGC=100, GOMEMLIMIT=512MB
Initial heap: 64 KB
After workload: 10240 KB, GCs: 0, Pause: 0 μs
</code></pre> Strategy Configuration Trade-off Default balanced <code>GOGC=100</code> Good general-purpose settings Memory-constrained <code>GOGC=20</code>, <code>GOMEMLIMIT=256MB</code> More GC cycles, lower memory Low latency <code>GOGC=200</code> Fewer GC cycles, higher memory Batch processing <code>GOGC=off</code> No GC overhead, unbounded growth Container environments <code>GOMEMLIMIT=container_limit</code> Respects container memory limits

