import (
    "flag"
    "fmt"
    "os"
)

func main() {
    verbose := flag.Bool("verbose", false, "Enable verbose output")
    flag.Parse()

    // Positional arguments come after flags
    args := flag.Args()

    if len(args) == 0 {
        fmt.Println("No files specified")
        fmt.Println("Usage: program [options] &lt;file1&gt; &lt;file2&gt; ...")
        os.Exit(1)
    }

    if *verbose {
        fmt.Printf("Processing %d files\n", len(args))
    }

    for _, filename := range args {
        fmt.Printf("Processing: %s\n", filename)
    }
}
</code></pre> <ul> <li>flag.Args: Returns remaining non-flag arguments</li> <li>Positional args: Arguments after all flags are parsed</li> <li>os.Exit(1): Non-zero exit code indicates error</li> <li>Usage: Show usage when required args missing</li> </ul> <pre><code>$ go run main.go -verbose file1.txt file2.txt file3.txt
