The CodeThe ExplanationThe Terminal Output <pre><code>package main

import (
    "fmt"
    "os"
    "path/filepath"
)

func main() {
    root := "."

    fmt.Printf("Walking directory tree from: %s\n\n", root)

    err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
        if err != nil {
            return err
        }

        indent := ""
        for i := 0; i &lt; len(path)-len(root); i++ {
            if path[i] == '/' {
                indent += "  "
            }
        }

        if info.IsDir() {
            fmt.Printf("%s[DIR]  %s/\n", indent, info.Name())
        } else {
            fmt.Printf("%s[FILE] %s (%d bytes)\n", indent, info.Name(), info.Size())
        }

        return nil
    })

    if err != nil {
        fmt.Println("Error walking:", err)
    }
}
</code></pre> <ul> <li>filepath.Walk: Recursively traverses directory tree</li> <li>WalkFunc: Called for each file/directory</li> <li>info.IsDir: Distinguishes files from directories</li> <li>Error handling: Return error to stop walking</li> </ul> <pre><code>Walking directory tree from: .

