func NewAPIKeyConfig() *APIKeyConfig {
    return &amp;APIKeyConfig{
        HeaderName: "X-API-Key",
        QueryParam: "api_key",
        HMACSecret: []byte("your-hmac-secret"),
        Expiry:     24 * time.Hour,
    }
