func (s *SessionStore) Create(userID, username string, duration time.Duration) (string, error) {
    bytes := make([]byte, 32)
    if _, err := rand.Read(bytes); err != nil {
        return "", err
    }
    sessionID := hex.EncodeToString(bytes)

    s.mu.Lock()
    defer s.mu.Unlock()

