func NewIPFilter() *IPFilter {
    return &amp;IPFilter{
        allowedCIDRs: make([]*net.IPNet, 0),
        blockedCIDRs: make([]*net.IPNet, 0),
        blockedIPs:   make(map[string]bool),
    }
