func (f *IPFilter) AllowCIDR(cidr string) error {
    _, ipNet, err := net.ParseCIDR(cidr)
    if err != nil {
        return err
    }

    f.mu.Lock()
    defer f.mu.Unlock()
    f.allowedCIDRs = append(f.allowedCIDRs, ipNet)
    return nil
}

func (f *IPFilter) BlockCIDR(cidr string) error {
    _, ipNet, err := net.ParseCIDR(cidr)
    if err != nil {
        return err
    }

    f.mu.Lock()
    defer f.mu.Unlock()
    f.blockedCIDRs = append(f.blockedCIDRs, ipNet)
    return nil
}

func (f *IPFilter) BlockIP(ip string) {
    f.mu.Lock()
    defer f.mu.Unlock()
    f.blockedIPs[ip] = true
}

func (f *IPFilter) IsAllowed(ip string) bool {
    f.mu.RLock()
    defer f.mu.RUnlock()

    // Check blocked IPs
    if f.blockedIPs[ip] {
        return false
    }

    // Parse IP
    parsedIP := net.ParseIP(ip)
    if parsedIP == nil {
        return false
    }

    // Check blocked CIDRs
    for _, cidr := range f.blockedCIDRs {
        if cidr.Contains(parsedIP) {
            return false
        }
    }

    // If no allowed CIDRs specified, allow all
    if len(f.allowedCIDRs) == 0 {
        return true
    }

    // Check allowed CIDRs
    for _, cidr := range f.allowedCIDRs {
        if cidr.Contains(parsedIP) {
            return true
        }
    }

    return false
}

func (f *IPFilter) Middleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        ip := r.RemoteAddr
        if forwarded := r.Header.Get("X-Forwarded-For"); forwarded != "" {
            ip = strings.Split(forwarded, ",")[0]
        }

        if !f.IsAllowed(ip) {
            http.Error(w, "Forbidden", http.StatusForbidden)
            return
        }

        next.ServeHTTP(w, r)
    })
}

